## New Proto Messages Needed

### hermes-substream/proto/schema.proto

Add these new message types:

```protobuf
message SpaceTypeDeclared {
    bytes space_id = 1;        // 16 bytes - from both from_id and to_id (same)
    bytes space_type = 2;      // 32 bytes - from topic field (e.g., keccak256("DAO_SPACE"))
    bytes version = 3;         // variable - from data field (e.g., "1.0.0" encoded)
}

message SpaceTypeDeclaredList {
    repeated SpaceTypeDeclared declarations = 1;
}

message SpaceCleared {
    bytes space_id = 1;        // 16 bytes - from from_id
    bytes space_address = 2;   // 20 bytes - from topic field
}

message SpaceClearedList {
    repeated SpaceCleared spaces = 1;
}

message ProposalSettingsUsed {
    bytes space_id = 1;        // 16 bytes
    bytes proposal_id = 2;     // 16 bytes - from topic field (bytes16 padded to 32)
    bytes data = 3;            // abi.encode(startDate, lastDate, votingMode, quorum, supportThreshold)
}

message ProposalSettingsUsedList {
    repeated ProposalSettingsUsed settings = 1;
}

message ProposalUpdated {
    bytes space_id = 1;        // 16 bytes
    bytes proposal_id = 2;     // 16 bytes - from topic field
    bytes data = 3;            // abi.encode(bytes16, VotingMode, Action[])
}

message ProposalUpdatedList {
    repeated ProposalUpdated proposals = 1;
}
```

## New Map Functions Needed

### hermes-substream/src/lib.rs

Add map functions following the existing pattern:

```rust
#[substreams::handlers::map]
fn map_space_types_declared(
    block: eth::v2::Block,
) -> Result<SpaceTypeDeclaredList, substreams::errors::Error> {
    let declarations: Vec<SpaceTypeDeclared> = block
        .logs()
        .filter_map(|log| parse_action(log))
        .filter(|action| action.action.as_slice() == ACTION_SPACE_TYPE_DECLARED)
        .map(|action| SpaceTypeDeclared {
            space_id: action.from_id,  // from_id == to_id for this action
            space_type: action.topic.clone(),
            version: action.data.clone(),
        })
        .collect();

    Ok(SpaceTypeDeclaredList { declarations })
}

#[substreams::handlers::map]
fn map_spaces_cleared(
    block: eth::v2::Block,
) -> Result<SpaceClearedList, substreams::errors::Error> {
    let spaces: Vec<SpaceCleared> = block
        .logs()
        .filter_map(|log| parse_action(log))
        .filter(|action| action.action.as_slice() == ACTION_SPACE_ID_CLEARED)
        .map(|action| SpaceCleared {
            space_id: action.from_id,
            space_address: action.topic[12..32].to_vec(),
        })
        .collect();

    Ok(SpaceClearedList { spaces })
}

// Similar for map_proposal_settings_used and map_proposals_updated
```

